<link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet">
<style>
[hidden]{display:none!important}
:root{font-family:'Plus Jakarta Sans',Arial,sans-serif;color:#17233e;background:#edf3fb}*{box-sizing:border-box}body{margin:0;min-height:100vh}button{font:inherit;cursor:pointer}button:focus-visible{outline:3px solid #3576e5;outline-offset:3px}.shell{max-width:1100px;margin:auto;padding:28px 22px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px}.brand{display:flex;align-items:center;gap:10px;font-size:19px;font-weight:800}.brandmark{display:grid;place-items:center;width:38px;height:38px;color:white;background:#183e9c;border-radius:12px}.logout{border:1px solid #cad5e7;background:white;color:#34425e;border-radius:12px;padding:10px 16px;font-weight:700}.intro{margin:10vh 0 30px}.intro h1{font-size:clamp(30px,4vw,46px);margin:0 0 10px}.intro p{color:#64748b}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.card{display:flex;flex-direction:column;align-items:flex-start;text-align:left;gap:18px;min-height:270px;width:100%;border:1px solid #d6e1f2;background:white;border-radius:24px;padding:30px;box-shadow:0 16px 38px #1932590d;transition:transform .18s,box-shadow .18s,border-color .18s}.card:hover{transform:translateY(-3px);box-shadow:0 22px 48px #1932591a;border-color:#83a7ed}.icon{display:grid;place-items:center;width:56px;height:56px;border-radius:17px;font-size:24px;background:#e9efff;color:#2453b8}.marketplace .icon{background:#fff0e4;color:#ca6423}.card h2{font-size:20px;margin:0}.card p{color:#64748b;line-height:1.6;margin:0}.action{margin-top:auto;color:#2453b8;font-weight:800}.marketplace .action{color:#b95016}.backdrop{position:fixed;inset:0;background:#15264691;backdrop-filter:blur(7px);display:grid;place-items:center;padding:20px;z-index:10}.dialog{width:min(950px,100%);max-height:calc(100vh - 40px);overflow:auto;background:#f8fbff;border-radius:28px;padding:clamp(22px,4vw,42px);box-shadow:0 28px 100px #0d214c55;position:relative}.dialog-head{display:flex;justify-content:space-between;align-items:start;gap:16px}.eyebrow{color:#2453b8;font-size:11px;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.dialog h1{font-size:clamp(26px,3vw,35px);margin:8px 0}.dialog .lead{color:#64748b;margin:0 0 10px}.hello{font-size:13px;color:#475569;margin:0 0 25px}.dialog .card{min-height:260px}.error{display:none;color:#a31d36;background:#fff1f2;border:1px solid #fecdd3;border-radius:12px;padding:12px;margin:0 0 16px}.error.show{display:block}.retry{border:0;background:transparent;text-decoration:underline;color:inherit;font-weight:800}.close{border:0;background:#e9eef8;border-radius:10px;width:36px;height:36px}.foot{display:flex;justify-content:space-between;align-items:center;margin-top:24px;gap:12px;color:#64748b;font-size:12px}button:disabled{opacity:.58;cursor:wait}@media(max-width:680px){.cards{grid-template-columns:1fr}.intro{margin:7vh 0 20px}.card,.dialog .card{min-height:220px;padding:22px}.dialog{border-radius:22px}.foot{flex-wrap:wrap}}@media(prefers-reduced-motion:reduce){.card{transition:none}.card:hover{transform:none}}
</style></head><body>
<main class="shell" inert id="pageContent"><div class="top"><div class="brand"><span class="brandmark">JL</span> Jago Laba</div><button class="logout" type="button" id="logoutTop">Keluar</button></div>
