<div class="dialog-head"><div><span class="eyebrow">JAGO LABA · RUANG KERJA</span><h1 id="dialogTitle">Selamat datang di Jago Laba</h1><p class="lead" id="dialogDescription">Pilih ruang kerja untuk mulai mengelola bisnis Anda.</p></div><button class="close" id="closeDialog" type="button" aria-label="Tutup dialog"><i class="fa-solid fa-xmark" aria-hidden="true"></i></button></div>
<p class="hello">Halo, <strong><?= $name ?></strong></p><div id="error" class="error" role="alert"></div><div class="cards" id="dialogCards"></div>
<div class="foot"><span>Ruang kerja aktif hanya berubah setelah Anda memilih.</span><button class="logout" id="logoutDialog" type="button">Keluar dari akun</button></div>
</section></div>
<script>
const allowed=<?= json_encode($allowed) ?>, csrf=<?= json_encode(Workspace::csrf()) ?>;
const data={konveksi:{title:'Manajemen Konveksi',description:'Kelola produksi, bahan baku, HPP, persediaan, dan keuangan konveksi.',button:'Masuk ke Konveksi',icon:'fa-shirt'},marketplace:{title:'Manajemen Marketplace',description:'Pantau pesanan, laba, pencairan dana, iklan, dan retur marketplace.',button:'Masuk ke Marketplace',icon:'fa-store'}};
let busy=false,lastChoice=null;
const overlay=document.getElementById('overlay'),dialog=document.getElementById('dialog'),error=document.getElementById('error');
function cards(parent){for(const key of allowed){const d=data[key],b=document.createElement('button');b.type='button';b.className='card '+key;b.innerHTML=`<span class="icon"><i class="fa-solid ${d.icon}" aria-hidden="true"></i></span><h2>${d.title}</h2><p>${d.description}</p><span class="action">${d.button} <i class="fa-solid fa-arrow-right" aria-hidden="true"></i></span>`;b.addEventListener('click',()=>choose(key));parent.appendChild(b)}}
cards(document.getElementById('pageCards'));cards(document.getElementById('dialogCards'));
async function choose(key){if(busy)return;busy=true;lastChoice=key;error.classList.remove('show');document.querySelectorAll('.card').forEach(b=>b.disabled=true);const action=document.querySelector('.dialog .'+key+' .action');if(action)action.textContent='Membuka ruang kerja…';try{const body=new URLSearchParams({workspace:key,csrf});const response=await fetch('api/workspace.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded','X-CSRF-Token':csrf},body});const result=await response.json();if(!response.ok||!result.success)throw new Error(result.message||'Gagal membuka ruang kerja.');localStorage.removeItem('jl_active_tab');localStorage.removeItem('jl_cache_db_v1');localStorage.removeItem('jl_cache_time_v1');sessionStorage.removeItem('jl_marketplace_store');location.assign(result.url)}catch(e){error.textContent=e.message+' ';const retry=document.createElement('button');retry.className='retry';retry.textContent='Coba lagi';retry.onclick=()=>choose(lastChoice);error.appendChild(retry);error.classList.add('show');document.querySelectorAll('.card').forEach(b=>b.disabled=false);if(action)action.innerHTML=data[key].button+' <i class="fa-solid fa-arrow-right" aria-hidden="true"></i>';busy=false}}
function close(){overlay.hidden=true;document.getElementById('pageContent').inert=false;document.getElementById('pageCards').querySelector('.card')?.focus()}
document.getElementById('closeDialog').onclick=close;
document.addEventListener('keydown',e=>{if(overlay.hidden)return;if(e.key==='Escape'){close();return}if(e.key==='Tab'){const nodes=[...dialog.querySelectorAll('button:not([disabled])')];const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
async function logout(){await fetch('api/logout.php',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':csrf}});location.assign('index.php')}
document.getElementById('logoutTop').onclick=logout;document.getElementById('logoutDialog').onclick=logout;
dialog.focus();
</script><?php require (dirname(__DIR__, 3) . '/app/Modules/Marketplace/Views/browser_auto_sync_driver.php'); ?></body></html>
